PAG6::cv.text:
def cv (p K v : ℕ) : ℤ :=
  if v = K then 1
  else if K ≤ 2 * v then (Nat.totient (p ^ (K - v)) : ℤ)
  else if 2 * v + 1 = K then -((p : ℤ) ^ (K - v - 1))
  else 0

PAG6::dj.text:
def dj (p K j : ℕ) : ℤ :=
  if j = 0 then 1
  else if 2 * j ≤ K then (Nat.totient (p ^ j) : ℤ)
  else if 2 * j = K + 1 then -((p : ℤ) ^ (j - 1))
  else 0

PAG27::Wproj.text:
def Wproj : ProjLine N → ProjLine N :=
  Quotient.lift (fun v => mk ⟨(v.1.2, v.1.1), swap_unimod v⟩)
    (fun _v _w ⟨u, h1, h2⟩ => mk_eq_mk u h2 h1)

PAG33::card_prim.text:
theorem card_prim (hc : 1 ≤ c) :
    Fintype.card {χ : DirichletCharacter ℂ (p ^ (c + 1)) // χ.IsPrimitive}
      = (p ^ (c + 1)).totient - (p ^ c).totient

PAG33::card_mul_not_prim.text:
theorem card_mul_not_prim (hc : 1 ≤ c) (χ₁ : DirichletCharacter ℂ (p ^ (c + 1))) (h₁ : χ₁.IsPrimitive) :
    Fintype.card {χ₂ : DirichletCharacter ℂ (p ^ (c + 1)) // χ₂.IsPrimitive ∧ ¬ (χ₁ * χ₂).IsPrimitive}
      = (p ^ c).totient

PAG33::card_mul_prim.text:
theorem card_mul_prim (hc : 1 ≤ c) (χ₁ : DirichletCharacter ℂ (p ^ (c + 1))) (h₁ : χ₁.IsPrimitive) :
    Fintype.card {χ₂ : DirichletCharacter ℂ (p ^ (c + 1)) // χ₂.IsPrimitive ∧ (χ₁ * χ₂).IsPrimitive}
      = (p ^ (c + 1)).totient - (p ^ c).totient - (p ^ c).totient

PAG49::caseI.text:
def caseI (K w₁ n₁ w₂ n₂ : ℕ) (h₁ : w₁ + (n₁ + 1) ≤ K) (h₂ : w₂ + (n₂ + 1) ≤ K)
    (χ₁ : DirichletCharacter ℂ (p ^ (n₁ + 1))) (χ₂ : DirichletCharacter ℂ (p ^ (n₂ + 1))) : Prop :=
  K - (n₁ + 1) - w₁ ≠ K - (n₂ + 1) - w₂ ∧ conv (ket K w₁ (n₁ + 1) h₁ χ₁) (ket K w₂ (n₂ + 1) h₂ χ₂) = 0

PAG49::caseIII.text:
def caseIII (K w₁ n₁ w₂ n₂ : ℕ) (h₁ : w₁ + (n₁ + 1) ≤ K) (h₂ : w₂ + (n₂ + 1) ≤ K)
    (χ₁ : DirichletCharacter ℂ (p ^ (n₁ + 1))) (χ₂ : DirichletCharacter ℂ (p ^ (n₂ + 1))) : Prop :=
  w₁ = w₂ ∧ n₁ = n₂ ∧ conv (ket K w₁ (n₁ + 1) h₁ χ₁) (ket K w₂ (n₂ + 1) h₂ χ₂) = χ₁ (-1) • ballB (p := p) K w₁ n₁

PAG54::family.text:
def family (K : ℕ) : Set (ZMod (p ^ K) → ℂ) :=
  {f | (∃ w c, ∃ h : w + c ≤ K, 1 ≤ c ∧ ∃ ψ : DirichletCharacter ℂ (p ^ c), ψ.IsPrimitive ∧ f = ket K w c h ψ) ∨
    (∃ w, ∃ hw : w < K, f = shellInd K w hw) ∨ f = Pi.single 0 1}

PAG90::KetDual.text:
def KetDual (K a : ℕ) (f : ZMod (p ^ K) → ℂ) : Prop :=
  ∃ w n : ℕ, ∃ h : w + (n + 1) ≤ K, ∃ χ : DirichletCharacter ℂ (p ^ (n + 1)), χ.IsPrimitive ∧
    K - (n + 1) - w = a ∧ f = ket K w (n + 1) h χ

PAG122::Unif.text:
def Unif (T : Finset α) (F : α → ℂ) (t₀ : α) (o : ℕ) : Prop :=
  t₀ ∈ T ∧ 0 < o ∧ F t₀ ≠ 0 ∧ (∀ t ∈ T, (F t / F t₀) ^ o = 1) ∧
    (∀ ξ : ℂ, ξ ^ o = 1 → o * (T.filter (fun t => F t = F t₀ * ξ)).card = T.card)

PAG125::unif_attach.text:
theorem unif_attach {β : Type*} [DecidableEq β] {T : Finset β} {F : β → ℂ} {t₀ : β} {o : ℕ}
    (h : Unif T F t₀ o) (ht₀ : t₀ ∈ T) :
    Unif (univ : Finset T) (fun x => F x) ⟨t₀, ht₀⟩ o

PAG145::fiber_eq.text:
theorem fiber_eq (t : ZMod (p ^ (c - k))) :
    #{χ : DirichletCharacter ℂ (p ^ c) | freq hkc h2k χ = t}
      = #{χ : DirichletCharacter ℂ (p ^ c) | freq hkc h2k χ = 0}

PAG150::range_digit_eq.text:
theorem range_digit_eq (a : (ZMod q)ˣ) (N : ℕ) :
    (Set.range fun ψ : DirichletCharacter ℂ q => ψ (a : ZMod q) ^ N)
      = {x : ℂ | x ^ (orderOf a / Nat.gcd (orderOf a) N) = 1}

PAG162::fiber_const.text:
open Classical in
theorem fiber_const (N : ℕ) (hω : ∀ t : ZMod p, ∃ ω : DirichletCharacter ℂ (p ^ c), ω ^ N = 1 ∧ fp hkc h2k ω = t)
    (t : ZMod p) :
    #{χ : DirichletCharacter ℂ (p ^ c) | χ ^ N = 1 ∧ fp hkc h2k χ = t}
      = #{χ : DirichletCharacter ℂ (p ^ c) | χ ^ N = 1 ∧ fp hkc h2k χ = 0}

PAG162::count_set.text:
open Classical in
theorem count_set (N : ℕ) (hω : ∀ t : ZMod p, ∃ ω : DirichletCharacter ℂ (p ^ c), ω ^ N = 1 ∧ fp hkc h2k ω = t)
    (S : Finset (ZMod p)) :
    #{χ : DirichletCharacter ℂ (p ^ c) | χ ^ N = 1 ∧ fp hkc h2k χ ∈ S}
      = S.card * #{χ : DirichletCharacter ℂ (p ^ c) | χ ^ N = 1 ∧ fp hkc h2k χ = 0}

PAG162::card_res.text:
open Classical in
theorem card_res (hp2 : p ≠ 2) (ε : ℂ) (hε : ε ^ 2 = 1) :
    #{t : ZMod p | t ≠ 0 ∧ Lc p (-t * 2⁻¹) = ε} = #{t : ZMod p | t ≠ 0 ∧ Lc p (-t * 2⁻¹) ≠ ε}

PAG162::half_half.text:
open Classical in
theorem half_half (h4 : p % 4 = 1) (n m : ℕ) (hnm : n + 1 = 2 * m + 1) (hm : 1 ≤ m) :
    #{χ : DirichletCharacter ℂ (p ^ (n + 1)) | ¬ 2 ∣ orderOf χ ∧ χ.IsPrimitive ∧
        orderOf ((gaussSum χ stdAddChar / ((Real.sqrt ((p : ℝ) ^ (n + 1)) : ℝ) : ℂ)) ^ orderOf χ) = p}
      = #{χ : DirichletCharacter ℂ (p ^ (n + 1)) | ¬ 2 ∣ orderOf χ ∧ χ.IsPrimitive ∧
        orderOf ((gaussSum χ stdAddChar / ((Real.sqrt ((p : ℝ) ^ (n + 1)) : ℝ) : ℂ)) ^ orderOf χ) ≠ p}

PAG164::count_three.text:
open Classical in
theorem count_three (h4 : p % 4 = 3) (n m : ℕ) (hnm : n + 1 = 2 * m + 1) (hm : 1 ≤ m) :
    #{χ : DirichletCharacter ℂ (p ^ (n + 1)) | χ.IsPrimitive ∧ orderOf (zeta n χ) = 4 * p}
        = (p - 1) * (p ^ (n - 1) * ((p - 1) / 2)) ∧
      #{χ : DirichletCharacter ℂ (p ^ (n + 1)) | χ.IsPrimitive ∧ orderOf (zeta n χ) = 2 * p}
        = (p - 1) * (p ^ (n - 1) * ((p - 1) / 2))

PAG185::jacobi_val.text:
theorem jacobi_val {A : Subalgebra ℤ ℂ} {χA : MulChar (ZMod p) A} {χ : MulChar (ZMod p) ℂ}
    (hval : χA.ringHomComp A.val.toRingHom = χ) (s t : ℕ) :
    jacobiSum (χ ^ s) (χ ^ t) = ((jacobiSum (χA ^ s) (χA ^ t) : A) : ℂ)

PAG185::jacobi_ev.text:
theorem jacobi_ev {A : Subalgebra ℤ ℂ} {χA : MulChar (ZMod p) A} {ev : A →+* ZMod p} {k : ℕ}
    (hev : χA.ringHomComp ev = powChar k) (s t : ℕ) :
    ev (jacobiSum (χA ^ s) (χA ^ t)) = jacobiSum (powChar (k * s)) (powChar (k * t))

PAG185::z_pow_mul_Pjbar.text:
theorem z_pow_mul_Pjbar (χ : MulChar (ZMod p) ℂ) (hn : 3 ≤ orderOf χ) {ψ : AddChar (ZMod p) ℂ}
    (hψ : ψ.IsPrimitive) :
    (gaussSum χ ψ / ((Real.sqrt p : ℝ) : ℂ)) ^ (2 * orderOf χ) * Pjbar χ = Pj χ

PAG185::Pj_pow_eq_of_root.text:
theorem Pj_pow_eq_of_root (χ : MulChar (ZMod p) ℂ) (hn : 3 ≤ orderOf χ) {ψ : AddChar (ZMod p) ℂ}
    (hψ : ψ.IsPrimitive) (N : ℕ) (h : (gaussSum χ ψ / ((Real.sqrt p : ℝ) : ℂ)) ^ N = 1) :
    Pj χ ^ N = Pjbar χ ^ N

PAG185::gauss_not_root.text:
theorem gauss_not_root (χ : MulChar (ZMod p) ℂ) (hn : 3 ≤ orderOf χ) {ψ : AddChar (ZMod p) ℂ}
    (hψ : ψ.IsPrimitive) (N : ℕ) (hN : 0 < N) :
    (gaussSum χ ψ / ((Real.sqrt p : ℝ) : ℂ)) ^ N ≠ 1

PAG190::map_alphaA.text:
theorem map_alphaA (χA : MulChar (ZMod p) A) (n j : ℕ) (f : A →+* ℂ) {χ' : MulChar (ZMod p) ℂ}
    (hf : χA.ringHomComp f = χ') :
    f (alphaA χA n j) = ((p : ℂ) * ∏ i ∈ Ico 1 (n - 1), jacobiSum χ' (χ' ^ i)) ^ (2 * j)

PAG190::map_betaA.text:
theorem map_betaA (χA : MulChar (ZMod p) A) (n j : ℕ) (f : A →+* ℂ) {χ' : MulChar (ZMod p) ℂ}
    (hf : χA.ringHomComp f = χ') :
    f (betaA χA n j) = (p : ℂ) ^ n * (∏ i ∈ Ico 1 j, jacobiSum χ' (χ' ^ i)) ^ (2 * n)

PAG190::norm_prod_z.text:
theorem norm_prod_z (χ' : MulChar (ZMod p) ℂ) (n : ℕ) (hord : orderOf χ' = n) {ψ : AddChar (ZMod p) ℂ}
    (hψ : ψ.IsPrimitive) (a : ℕ → ℤ) :
    ‖∏ j ∈ Ico 1 n, ((gaussSum (χ' ^ j) ψ / ((Real.sqrt p : ℝ) : ℂ)) ^ (2 * n)) ^ a j‖ = 1

PAG208::Vs_eq_span_ket.text:
theorem Vs_eq_span_ket (s n N : ℕ) [NeZero N] (h : s * n = N) :
    Vs N s = Submodule.span ℂ {g | ∃ (c : ℕ) (hcn : c ∣ n) (χ : DirichletCharacter ℂ c), χ.IsPrimitive ∧
      g = PAG.Part15.conv (geps N s) (gket (n / c) (s * c) N (dual_shell_eq h hcn) c (dvd_mul_left c s) χ)}

PAG216::geps_conv_gblock.text:
theorem geps_conv_gblock (N c : ℕ) [NeZero N] (hcN : c ∣ N) (χ : DirichletCharacter ℂ c) {v : ℕ}
    (hv : v ∣ N / c) (s : ℕ) :
    PAG.Part15.conv (geps N s) (gblock N c χ v) = if s = N / (v * c) then gblock N c χ v else 0

PAG217::dind_mul_dft_gblock.text:
theorem dind_mul_dft_gblock (N c : ℕ) [NeZero N] (hcN : c ∣ N) (χ : DirichletCharacter ℂ c) {v : ℕ}
    (hv : v ∣ N / c) (s : ℕ) :
    dind N s * 𝓕 (gblock N c χ v) = if s = N / (v * c) then 𝓕 (gblock N c χ v) else 0

PAG220::dft_gblock_support.text:
theorem dft_gblock_support (N c : ℕ) [NeZero N] [NeZero c] (hcN : c ∣ N) (χ : DirichletCharacter ℂ c) {w : ℕ}
    (hw : w ∣ N / c) (x : ZMod N) (hx : 𝓕 (gblock N c χ⁻¹ w) x ≠ 0) :
    ∃ y : ℕ, x.val = N / (w * c) * y ∧ Nat.Coprime y c

PAG220::dft_gblock_layer.text:
theorem dft_gblock_layer (N c : ℕ) [NeZero N] [NeZero c] (hcN : c ∣ N) (χ : DirichletCharacter ℂ c) {w d : ℕ}
    (hw : w ∣ N / c) (hl : InLayer c d (N / (w * c))) (x : ZMod N) (hx : 𝓕 (gblock N c χ⁻¹ w) x ≠ 0) :
    InLayer c d x.val

PAG220::layerPart_apply_eq_zero.text:
theorem layerPart_apply_eq_zero (N c : ℕ) [NeZero N] (χ : DirichletCharacter ℂ c) {d d' : ℕ}
    (hd : RadDvd d c) (hd' : RadDvd d' c) (hne : d ≠ d') {f : ZMod N → ℂ} (hf : f ∈ layerPart N c χ d)
    (x : ZMod N) (hx : InLayer c d' x.val) : f x = 0

PAG220::layerPart_exists_apply.text:
theorem layerPart_exists_apply (N c : ℕ) [NeZero N] [NeZero c] (hcN : c ∣ N) (χ : DirichletCharacter ℂ c)
    (hχ : χ.IsPrimitive) {d : ℕ} (hdL : d ∣ N / c) (hd : RadDvd d c) {f : ZMod N → ℂ}
    (hf : f ∈ layerPart N c χ d) : ∃ S ∈ shellAlg N, S (gblock N c χ d) = f

PAG221::layerInd_mul_of_mem.text:
theorem layerInd_mul_of_mem (N c : ℕ) [NeZero N] (χ : DirichletCharacter ℂ c) {d d' : ℕ}
    (hd : RadDvd d c) (hd' : RadDvd d' c) {g : ZMod N → ℂ} (hg : g ∈ layerPart N c χ d') :
    layerInd N c d * g = if d = d' then g else 0

PAG222::twistV_comp_mem_blockComm.text:
theorem twistV_comp_mem_blockComm (N c : ℕ) [NeZero N] [NeZero c] (hcN : c ∣ N) (χ χ' : DirichletCharacter ℂ c)
    (hχ : χ.IsPrimitive) (hχ' : χ'.IsPrimitive) {T : blockSpan N c χ →ₗ[ℂ] blockSpan N c χ'}
    (hT : T ∈ blockHom N c c χ χ') : twistV N c hcN χ' χ ∘ₗ T ∈ blockComm N c χ

PAG224::blockHomExt_mem_fullComm.text:
theorem blockHomExt_mem_fullComm (N c c' : ℕ) [NeZero N] [NeZero c] (hcN : c ∣ N) (χ : DirichletCharacter ℂ c)
    (χ' : DirichletCharacter ℂ c') (hχ : χ.IsPrimitive) {X : blockSpan N c χ →ₗ[ℂ] blockSpan N c' χ'}
    (hX : X ∈ blockHom N c c' χ χ') : blockHomExt N c c' χ χ' X ∈ fullComm N

PAG224::commSum_commBlock.text:
theorem commSum_commBlock (N : ℕ) [NeZero N] [Fintype (BlockIdx N)] {T : Module.End ℂ (ZMod N → ℂ)}
    (hT : T ∈ fullComm N) (g : ZMod N → ℂ) :
    commSum N (fun p => ⟨commBlock N p.1 p.2 T, commBlock_mem N p.1 p.2 hT⟩) g = T g

PAG224::diagSum_commBlock.text:
theorem diagSum_commBlock (N : ℕ) [NeZero N] [Fintype (BlockIdx N)] {T : Module.End ℂ (ZMod N → ℂ)}
    (hT : T ∈ dilComm N) (g : ZMod N → ℂ) :
    diagSum N (fun b => ⟨commBlock N b b T, commBlock_mem N b b ((mem_dilComm N T).mp hT).1⟩) g = T g

PAG226::blockHom_exists_mul.text:
theorem blockHom_exists_mul (N c : ℕ) [NeZero N] [NeZero c] (hcN : c ∣ N) (χ χ' : DirichletCharacter ℂ c)
    (hχ : χ.IsPrimitive) (hχ' : χ'.IsPrimitive) {X : blockSpan N c χ →ₗ[ℂ] blockSpan N c χ'}
    (hX : X ∈ blockHom N c c χ χ') : ∃ ψ : ZMod N → ℂ, ∀ g : blockSpan N c χ, (X g : ZMod N → ℂ) = ψ * g

PAG226::centralElt_apply_of_mem.text:
theorem centralElt_apply_of_mem (N : ℕ) [NeZero N] [Fintype (BlockIdx N)] (c d : ℕ) {b₀ : BlockIdx N}
    {f : ZMod N → ℂ} (hf : f ∈ blockSpan N b₀.1 b₀.2.1) :
    centralElt N c d f = if (b₀.1 : ℕ) = c then layerInd N c d * f else 0

PAG226::center_preserves.text:
theorem center_preserves (N c : ℕ) [NeZero N] [NeZero c] (hcN : c ∣ N) (χ : DirichletCharacter ℂ c)
    (hχ : χ.IsPrimitive) {Z : Module.End ℂ (ZMod N → ℂ)} (hZ : Z ∈ fullCommCenter N) {f : ZMod N → ℂ}
    (hf : f ∈ blockSpan N c χ) : Z f ∈ blockSpan N c χ

PAG226::center_eq_sum.text:
theorem center_eq_sum (N : ℕ) [NeZero N] [Fintype (BlockIdx N)] {Z : Module.End ℂ (ZMod N → ℂ)}
    (hZ : Z ∈ fullCommCenter N) :
    Z = ∑ j : centerIdx N, centerCoef N Z j.1 • centralElt N j.1.1 j.1.2

PAG226::centralElt_apply_layer.text:
theorem centralElt_apply_layer (N : ℕ) [NeZero N] [Fintype (BlockIdx N)] (r p : centerIdx N)
    (χ : DirichletCharacter ℂ r.1.1) (hχ : χ.IsPrimitive) {g : ZMod N → ℂ}
    (hg : g ∈ layerPart N r.1.1 χ r.1.2) : centralElt N p.1.1 p.1.2 g = if p = r then g else 0

PAG233::idxMul_mem_centerIdx.text:
theorem idxMul_mem_centerIdx {a b : ℕ} (hab : Nat.Coprime a b) {ca da cb db : ℕ}
    (hp : (⟨ca, da⟩ : Σ _ : ℕ, ℕ) ∈ centerIdx a) (hq : (⟨cb, db⟩ : Σ _ : ℕ, ℕ) ∈ centerIdx b) :
    idxMul ⟨ca, da⟩ ⟨cb, db⟩ ∈ centerIdx (a * b)

PAG233::idxSplit_idxMul.text:
theorem idxSplit_idxMul {a b : ℕ} (hab : Nat.Coprime a b) {ca da cb db : ℕ}
    (hp : (⟨ca, da⟩ : Σ _ : ℕ, ℕ) ∈ centerIdx a) (hq : (⟨cb, db⟩ : Σ _ : ℕ, ℕ) ∈ centerIdx b) :
    idxSplit a b (idxMul ⟨ca, da⟩ ⟨cb, db⟩) = (⟨ca, da⟩, ⟨cb, db⟩)

PAG233::idxMul_idxSplit.text:
theorem idxMul_idxSplit {a b : ℕ} (hab : Nat.Coprime a b) {c d : ℕ}
    (hr : (⟨c, d⟩ : Σ _ : ℕ, ℕ) ∈ centerIdx (a * b)) :
    idxMul (idxSplit a b ⟨c, d⟩).1 (idxSplit a b ⟨c, d⟩).2 = ⟨c, d⟩

PAG233::primCount_idxMul.text:
theorem primCount_idxMul {a b : ℕ} (hab : Nat.Coprime a b) {ca da cb db : ℕ}
    (hp : (⟨ca, da⟩ : Σ _ : ℕ, ℕ) ∈ centerIdx a) (hq : (⟨cb, db⟩ : Σ _ : ℕ, ℕ) ∈ centerIdx b) :
    primCount (ca * cb) = primCount ca * primCount cb

PAG236::charMul_injective.text:
theorem charMul_injective {m n : ℕ} [NeZero m] [NeZero n] (hmn : Nat.Coprime m n)
    {χ₁ χ₁' : DirichletCharacter ℂ m} {χ₂ χ₂' : DirichletCharacter ℂ n}
    (h : charMul χ₁ χ₂ = charMul χ₁' χ₂') : χ₁ = χ₁' ∧ χ₂ = χ₂'

PAG236::crtProd_mem_blockSpan.text:
theorem crtProd_mem_blockSpan {a b ca cb : ℕ} [NeZero a] [NeZero b] [NeZero ca] [NeZero cb]
    (hab : Nat.Coprime a b) (hca : ca ∣ a) (hcb : cb ∣ b) {χa : DirichletCharacter ℂ ca}
    {χb : DirichletCharacter ℂ cb} (hχa : χa.IsPrimitive) (hχb : χb.IsPrimitive) {f : ZMod a → ℂ}
    {g : ZMod b → ℂ} (hf : f ∈ blockSpan a ca χa) (hg : g ∈ blockSpan b cb χb) :
    crtProd hab f g ∈ blockSpan (a * b) (ca * cb) (charMul χa χb)

PAG236::matUnit_self_eq.text:
theorem matUnit_self_eq (N c : ℕ) [NeZero N] [NeZero c] (χ : DirichletCharacter ℂ c) {d : ℕ}
    (hdI : d ∈ layerIdx c (N / c)) :
    matUnit N c d χ χ = LinearMap.mulLeft ℂ (layerInd N c d) * blockProjL N c χ

PAG238::gaugeP_ne_zero.text:
theorem gaugeP_ne_zero {a b : ℕ} (hab : Nat.Coprime a b) {ca da cb db : ℕ}
    (hp : (⟨ca, da⟩ : Σ _ : ℕ, ℕ) ∈ centerIdx a) (hq : (⟨cb, db⟩ : Σ _ : ℕ, ℕ) ∈ centerIdx b)
    (x : Prim ca × Prim cb) : gaugeP da db x ≠ 0

PAG240::CRTMul.text:
def CRTMul (X : ∀ (n : ℕ) [NeZero n], Subalgebra ℂ (Module.End ℂ (ZMod n → ℂ))) : Prop :=
  ∀ (a b : ℕ) [NeZero a] [NeZero b] (hab : Nat.Coprime a b),
    (X (a * b)).map (crtConj hab).toAlgHom = (X a).map (leftHom a b) ⊔ (X b).map (rightHom a b)

PAG242::card_layerDivs_primePow.text:
theorem card_layerDivs_primePow {q : ℕ} (hq : q.Prime) (k : ℕ) {p : Σ _ : ℕ, ℕ}
    (hp : p ∈ centerIdx (q ^ k)) :
    (layerDivs p.1 p.2 (q ^ k / p.1)).card = if p.1 = 1 then k + 1 else 1

PAG248::exists_apply_convL_geps_one.text:
theorem exists_apply_convL_geps_one {N : ℕ} [NeZero N] {X : Module.End ℂ (ZMod N → ℂ)}
    (hX : X ∈ dualOneEAlg N) : ∃ c : ℂ, ∀ h : ZMod N → ℂ, shellAvg N h = 0 →
      X (PAG.Part15.convL (geps N 1) h) = c • PAG.Part15.convL (geps N 1) h

PAG248::exists_apply_of_mem_dualOneEAlg.text:
theorem exists_apply_of_mem_dualOneEAlg {N : ℕ} [NeZero N] {X : Module.End ℂ (ZMod N → ℂ)}
    (hX : X ∈ dualOneEAlg N) : ∃ c : devSet N → ℂ, ∀ f : ZMod N → ℂ, shellAvg N f = 0 →
      X f = ∑ t : devSet N, c t • PAG.Part15.convL (geps N t) f

PAG251::oneEAlg_le_centralizer.text:
theorem oneEAlg_le_centralizer {N s p : ℕ} [NeZero N] (hs : s ∣ N) (hp : p.Prime) (hpN : p ∣ N)
    (hpp : p * p ∣ N / s) :
    oneEAlg N s ≤ Subalgebra.centralizer ℂ {LinearMap.mulLeft ℂ (charP N p)}

PAG251::dft_unitWit_of_mul_eq_zero.text:
theorem dft_unitWit_of_mul_eq_zero {N p m : ℕ} [NeZero N] {k : ZMod N}
    (hk : ((N / p ^ m : ℕ) : ZMod N) * k = 0) :
    𝓕 (unitWit N p m) k = (p : ℂ) ^ m * (stdAddChar (-k) - stdAddChar k)

PAG252::not_rhs_of_exceptional.text:
theorem not_rhs_of_exceptional {N s : ℕ}
    (hex : (∃ p, p.Prime ∧ p ≠ 2 ∧ N = p ^ 3 ∧ s = p) ∨ (N = 16 ∧ s = 2)) [NeZero N] :
    ¬ ((devSet N).card ≤ 2 ∨ (Squarefree N ∧ (s = 1 ∨ s = 2)))

PAG253::norm_eq_one_of_isometry.text:
theorem norm_eq_one_of_isometry {G : Type*} [CommGroup G] [Fintype G] (U : (G → ℂ) →ₗ[ℂ] (G → ℂ))
    (hiso : ∀ f g, ipG (U f) (U g) = ipG f g) (χ : G →* ℂˣ) {c : ℂ}
    (hc : U (PAG.charFun χ) = c • PAG.charFun χ) : ‖c‖ = 1

PAG259::padicValRat_prod_zpow.text:
theorem padicValRat_prod_zpow (S : Finset ℕ) (hS : ∀ s ∈ S, s.Prime) (k : ℕ → ℤ) {t : ℕ}
    (ht : t.Prime) :
    padicValRat t (∏ s ∈ S, (s : ℚ) ^ (k s)) = if t ∈ S then k t else 0

PAG259::sep_of_inf_unmeasured.text:
theorem sep_of_inf_unmeasured (M : Finset ℕ) {q r : ℚ}
    (hne : ∃ s ∈ M, padicValRat s q ≠ padicValRat s r) :
    ∃ s ∈ M, (1 : ℝ) ≤ |((padicValRat s q - padicValRat s r : ℤ) : ℝ)|

PAG259::imgST.text:
def imgST (S T : Finset ℕ) : Set (ℝ × (T → ℤ)) :=
  {z | ∃ q : ℚ, 0 < q ∧ (∀ t : ℕ, t.Prime → t ∉ S → padicValRat t q = 0) ∧
    z = (Real.log q, fun t : T => padicValRat (t : ℕ) q)}

PAG259::closure_rho_not_image.text:
theorem closure_rho_not_image :
    ((1 : ℝ), (0 : Nat.Primes → ℤ)) ∈ closure (rho '' {q : ℚ | 0 < q}) ∧
      ((1 : ℝ), (0 : Nat.Primes → ℤ)) ∉ rho '' {q : ℚ | 0 < q}

PAG259::exists_between_one.text:
theorem exists_between_one {p r : ℕ} (hp : p.Prime) (hr : r.Prime) (hne : p ≠ r) {y : ℝ}
    (hy : 1 < y) :
    ∃ a b : ℤ, 1 < (p : ℝ) ^ a * (r : ℝ) ^ b ∧ (p : ℝ) ^ a * (r : ℝ) ^ b < y

PAG260::crossSign_of_odd.text:
omit [NeZero M] [NeZero N] in
theorem crossSign_of_odd {χ₁ : DirichletCharacter ℂ M} {χ₂ : DirichletCharacter ℂ N}
    (h1 : χ₁.Odd) (h2 : χ₂.Odd) : crossSign χ₁ χ₂ = -1

PAG260::crossSign_of_even_right.text:
omit [NeZero M] [NeZero N] in
theorem crossSign_of_even_right (χ₁ : DirichletCharacter ℂ M) {χ₂ : DirichletCharacter ℂ N}
    (h2 : χ₂.Even) : crossSign χ₁ χ₂ = 1

PAG260::isPrimitive_prodChar.text:
theorem isPrimitive_prodChar (h : M.Coprime N) {χ₁ : DirichletCharacter ℂ M}
    {χ₂ : DirichletCharacter ℂ N} (h1 : χ₁.IsPrimitive) (h2 : χ₂.IsPrimitive) :
    (prodChar χ₁ χ₂).IsPrimitive
